--- a/training/level-1/L1-033-markdown-table/markdownTable.mjs
+++ b/training/level-1/L1-033-markdown-table/markdownTable.mjs
@@ -0,0 +1,31 @@
+export function markdownTable(records, options = {}) {
+  const columns = options.columns || Object.keys(records[0]).sort();
+
+  if (records.length === 0) return '';
+
+  const headerRow = columns.map(col => col);
+  const separatorRow = columns.map(() => '---');
+
+  const escapeCell = (value) => {
+    let str = String(value);
+    str = str.replace(/\\/g, '\\\\').replace(/\|/g, '\\|');
+    str = str.replace(/\r\n/g, '<br>').replace(/\r/g, '<br>').replace(/\n/g, '<br>');
+    return str;
+  };
+
+  const dataRows = records.map(record =>
+    columns.map(col => {
+      let val = record[col];
+      if (val === null || val === undefined) {
+        return '';
+      }
+      if (typeof val !== 'object' || Array.isArray(val)) {
+        throw new TypeError('Nested objects/arrays not allowed');
+      }
+      return escapeCell(val);
+    })
+  );
+
+  const lines = [headerRow.join('|'), separatorRow.join('|'), ...dataRows.map(row => row.join('|'))];
+  return lines.join('\n');
+}

